// CSD_RATIONALE_BEGIN
// Root-cause analysis of the 0.0% accuracy failure:
//   The previous strategy closed every constrained span as soon as
//   `parser.IsCompletePrefix` became true. For symbolic expressions, a lone
//   variable such as `n` is a valid complete parse, so spans were closed after
//   exactly 1 constrained token. The evaluator extracts the LAST visible span as
//   the answer, which was always a single variable like `<<n>>` or `<<price>>`.
//
// Two simultaneous fixes:
//   (A) Guidance: tell the model to write COMPLETE arithmetic expressions
//       combining all relevant variables in each `<< >>`, not lone variable names.
//   (B) Decoding: remove the eager `IsCompletePrefix` early-close branch.
//       Instead, keep generating constrained tokens until the LM naturally
//       chooses EOS, then close. For the first 5 tokens of each span, penalize
//       EOS by 10.0 so the model cannot prematurely terminate after a single
//       variable token. Only close when EOS is chosen AND the current constrained
//       prefix is complete. After a clean close, continue the loop (no break) to
//       allow further free text and additional intermediate spans; the evaluator
//       uses the last closed span, which will contain the full final expression.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Free branch (!insideConstrainedOut): implication is vacuously true.
//   On `<<` detection: insideConstrainedOut := true, currentConstrainedOut := [],
//   and parser.IsValidPrefix([]) holds by method precondition; invariant holds.
//   Constrained branch (no EOS): SafePenalizedConstrainedStep and
//   AdaptiveConstrainedStep both return EOS or a token valid at the current
//   constrained prefix; AppendConstrainedToken extends currentConstrainedOut by
//   exactly that token, preserving IsValidPrefix. Invariant holds.
//   EOS + complete branch: IsCompletePrefix is true, CloseConstrainedSpan
//   requires and uses that fact, sets insideConstrainedOut := false (implication
//   vacuous) and currentConstrainedOut := []. Invariant holds.
//   EOS without complete or budget: break with unchanged (still valid) state.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Free branch: steps increments by 1; generated grows by at most 1 visible
//   token (EOS is not appended, "<<" is 1 token). Bound preserved.
//   Constrained token step: steps increments by 1; AppendConstrainedToken grows
//   generated by exactly 1. Bound preserved.
//   CloseConstrainedSpan: steps increments by 1; CloseConstrainedSpan appends
//   at most 1 delimiter token (">>"). Visible growth <= 1 = steps growth. Bound
//   preserved.
//   EOS-without-close break: no appends, steps already incremented. Bound
//   preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Reason step by step. Each << >> span must contain a COMPLETE arithmetic expression that combines ALL relevant variables and numbers with operators (+, -, /, //, %, (), int()). For example write <<n1*w1 + n2*w2 - n3*w3>> not <<n1>>, <<n2>>, <<n3>> separately. NEVER put a lone variable name inside << >>. The FINAL answer line MUST be: The final answer is <<complete_combined_expression_using_all_variables_and_operations>>. Single variable names like <<n>> or <<price>> as the answer are WRONG.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var spanTokens: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
        spanTokens := 0;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next;
    if spanTokens < 5 {
      // Penalise EOS for first 5 tokens: prevents single-variable spans
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, [eosToken], 10.0, eosToken
      );
    } else {
      next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
    }
    steps := steps + 1;
    spanTokens := spanTokens + 1;
    if next == eosToken {
      // LM chose to stop: close if complete and budget remains
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
        // Do NOT break: allow continued free generation and further spans
      } else {
        break;
      }
    } else {
      var cg, ci, cc := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    }
  }
}

cost := steps;

